mapper.select:
/* isry.drmgs.casereg.mapper.DrmgsCaseRegMapper.onSchulwDscntcList - 응용2팀 강화영 */ /*사례목록을 참조로 만든 쿼리(selectCaseinqList):사례목록쿼리가 변경되면 확인후 변경해야함!!!!*/
SELECT /* selectCaseinqList - Lee JunYeong */ T1.CASE_MNG_NO AS CASE_MNG_NO /* 사례관리번호 */ , T1.CASE_MNG_ODRNO AS CASE_MNG_ODRNO /* 사례관리차수 */ , TO_CHAR(T1.FRST_REG_DT, 'YYYY-MM-DD') AS FRST_REG_DT /* 등록일자 */ , T2.TRPR_INFO_NO AS TRPR_INFO_NO /* 대상자정보번호 */ , C##RG.DEC_B64(CASE WHEN T3.INDV_IDNTFC_NO IS NULL THEN T2.TRPR_NM_ENCPT ELSE T3.FLNM_ENCPT END) AS TRPR_NM_ENCPT /* 대상자명 */ , TO_CHAR(TO_DATE(T2.TRPR_BRTH_YMD), 'YYYY-MM-DD') AS TRPR_BRTH_YMD /* 대상자출생일자 */ , CASE WHEN T3.INDV_IDNTFC_NO IS NULL THEN T2.SXDC_SE_CD ELSE T3.SXDC_SE_CD END AS SXDC_SE_CD /* 대상자성별구분코드 */ , T1.YNGBGS_STTS_LCLAS_SE_CD AS YNGBGS_STTS_LCLAS_SE_CD /* 청소년상태대분류구분코드 */ , T1.YNGBGS_STTS_SCLAS_SE_CD AS YNGBGS_STTS_SCLAS_SE_CD /* 청소년상태소분류구분코드 */ , C##RG.DEC_B64(T5.FLNM_ENCPT) AS PIC_NM_ENCPT /* 담당자명 */ , T6.INST_NM AS INST_NM /* 담당기관명 */ , T2.CASE_TRPR_TYPE_SE_CD AS CASE_TRPR_TYPE_SE_CD /* 사례대상자유형구분코드 */ , T1.CASE_PRGRS_STTS_SE_CD AS CASE_PRGRS_STTS_SE_CD /* 사례진행상태구분코드 */ , T1.UNT_TASKWK_SE_CD AS UNT_TASKWK_SE_CD /* 단위업무구분코드 */ ,(SELECT UP_CMMNS_CD_VALUE FROM SAC100 WHERE CMMNS_CD_ID = 'CASE_PRGRS_STTS_SE_CD' AND CMMNS_CD_VALUE = T1.CASE_PRGRS_STTS_SE_CD) AS CASE_PRGRS_STTS_TYPE_SE_CD /* 사례진행상태유형구분코드 */ , (select count(*) from SEB100 TT2 , SEB120 TT1 , SDA420 TT3 , SDA400 TT4 where TT2.CASE_MNG_NO = T1.CASE_MNG_NO and TT2.CASE_MNG_ODRNO = T1.CASE_MNG_ODRNO AND TT2.UNT_TASKWK_SE_CD = 'U03' AND TT1.CASE_MNG_NO = TT2.CASE_MNG_NO AND TT1.CASE_MNG_ODRNO = TT2.CASE_MNG_ODRNO and TT1.DEL_YN = 'N' AND TT1.SRVC_EXCN_BIZ_NO = TT3.SRVC_EXCN_BIZ_NO AND TT3.SRVC_BIZ_NO = TT4.SRVC_BIZ_NO AND TT4.BIZ_CL_SE_CD = '04' ) CNT1 , (select count(*) from AKA101 TT5 where TT5.CASE_MNG_NO = T1.CASE_MNG_NO and TT5.CASE_MNG_ODRNO = T1.CASE_MNG_ODRNO ) CNT2 FROM SEB100 T1 , SEA200 T2 , SCA300 T3 , SEB150 T4 , SCA100 T5 , SAA000 T6
WHERE 1 = 1 AND T1.TRPR_INFO_NO = T2.TRPR_INFO_NO AND T2.INDV_IDNTFC_NO = T3.INDV_IDNTFC_NO(+) AND T1.CASE_MNG_NO = T4.CASE_MNG_NO(+) AND T1.CASE_MNG_ODRNO = T4.CASE_MNG_ODRNO(+) AND T5.ENFSN_NO(+) = T4.CASE_PIC_NO AND T6.INST_NO(+) = T4.PIC_INST_NO AND T4.PCHPRS_YN(+) = 'Y'
AND TO_CHAR(T1.FRST_REG_DT, 'YYYYMMDD') BETWEEN #{START_DATE} AND #{END_DATE}
AND T2.TRPR_NM_ENCPT = #{TRPR_NM_ENCPT}
AND T1.YNGBGS_STTS_LCLAS_SE_CD = #{YNGBGS_STTS_LCLAS_SE_CD}
AND T1.YNGBGS_STTS_SCLAS_SE_CD = #{YNGBGS_STTS_SCLAS_SE_CD}
AND T5.FLNM_ENCPT = #{PIC_NM_ENCPT}
AND(T6.INST_NO = #{INST_NO} OR T6.INST_NM = #{INST_NM})
AND T2.CASE_TRPR_TYPE_SE_CD = #{CASE_TRPR_TYPE_SE_CD}
AND T1.CASE_PRGRS_STTS_SE_CD IN (SELECT CMMNS_CD_VALUE FROM SAC100 WHERE CMMNS_CD_ID = 'CASE_PRGRS_STTS_SE_CD' AND UP_CMMNS_CD_VALUE = #{CASE_PRGRS_STTS_SE_CD})
AND T1.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
AND REGEXP_LIKE(T1.TAG_NO, '(' || REPLACE(#{TAG_NO},',','|') || ')') -- 태그번호
AND T2.RCPT_PIC_NO = #{USER_ID}
ORDER BY T1.FRST_REG_DT DESC, T1.CASE_MNG_NO, T1.CASE_MNG_ODRNO DESC

/* isry.drmgs.casereg.mapper.DrmgsCaseRegMapper.selectOccpAbilitInsertList - 응용2팀 강화영 */ /*사례목록을 참조로 만든 쿼리(selectCaseinqList):사례목록쿼리가 변경되면 확인후 변경해야함!!!!*/ /* selectCaseinqList - Lee JunYeong */ T1.CASE_MNG_NO AS CASE_MNG_NO /* 사례관리번호 */ , T1.CASE_MNG_ODRNO AS CASE_MNG_ODRNO /* 사례관리차수 */ , TO_CHAR(T1.FRST_REG_DT, 'YYYY-MM-DD') AS FRST_REG_DT /* 등록일자 */ , T2.TRPR_INFO_NO AS TRPR_INFO_NO /* 대상자정보번호 */ , C##RG.DEC_B64(CASE WHEN T3.INDV_IDNTFC_NO IS NULL THEN T2.TRPR_NM_ENCPT ELSE T3.FLNM_ENCPT END) AS TRPR_NM_ENCPT /* 대상자명 */ , DECODE(T2.TRPR_BRTH_YMD, '-', '', TO_CHAR(TO_DATE(T2.TRPR_BRTH_YMD), 'YYYY-MM-DD')) AS TRPR_BRTH_YMD /* 대상자출생일자 */ , CASE WHEN T3.INDV_IDNTFC_NO IS NULL THEN T2.SXDC_SE_CD ELSE T3.SXDC_SE_CD END AS SXDC_SE_CD /* 대상자성별구분코드 */ , T1.YNGBGS_STTS_LCLAS_SE_CD AS YNGBGS_STTS_LCLAS_SE_CD /* 청소년상태대분류구분코드 */ , T1.YNGBGS_STTS_SCLAS_SE_CD AS YNGBGS_STTS_SCLAS_SE_CD /* 청소년상태소분류구분코드 */ , T1.YNGBGS_SE_NO AS YNGBGS_SE_NO /* 청소년구분번호 */ , C##RG.DEC_B64(T5.FLNM_ENCPT) AS PIC_NM_ENCPT /* 담당자명 */ , T6.INST_NM AS INST_NM /* 담당기관명 */ , T2.CASE_TRPR_TYPE_SE_CD AS CASE_TRPR_TYPE_SE_CD /* 사례대상자유형구분코드 */ , T1.CASE_PRGRS_STTS_SE_CD AS CASE_PRGRS_STTS_SE_CD /* 사례진행상태구분코드 */ , T1.UNT_TASKWK_SE_CD AS UNT_TASKWK_SE_CD /* 단위업무구분코드 */ ,(SELECT UP_CMMNS_CD_VALUE FROM SAC100 WHERE CMMNS_CD_ID = 'CASE_PRGRS_STTS_SE_CD' AND CMMNS_CD_VALUE = T1.CASE_PRGRS_STTS_SE_CD) AS CASE_PRGRS_STTS_TYPE_SE_CD /* 사례진행상태유형구분코드 */ , T7.REPA_YN /*재참여여부*/ , ( CASE WHEN T7.STG4_ENTRY_WAIT_YMD IS NOT NULL THEN '4단계' ELSE ( CASE WHEN T7.STG3_ENTRY_WAIT_YMD IS NOT NULL THEN '3단계' ELSE ( CASE WHEN T7.STG2_ENTRY_WAIT_YMD IS NOT NULL THEN '2단계' ELSE ( CASE WHEN T7.STG1_PTCPTN_STTS_SE_CD IS NOT NULL THEN '1단계' ELSE '' END ) END ) END ) END ) STEP_TOT /*참여상태-단계*/ , ( CASE WHEN T7.STG4_MDSTRM_FAILR_YMD IS NOT NULL OR T7.STG3_MDSTRM_FAILR_YMD IS NOT NULL OR T7.STG2_MDSTRM_FAILR_YMD IS NOT NULL THEN '중도탈락' ELSE ( CASE WHEN T7.STG4_FNSH_YMD IS NOT NULL OR T7.STG3_FNSH_YMD IS NOT NULL OR T7.STG2_FNSH_YMD IS NOT NULL THEN '수료' ELSE ( CASE WHEN T7.STG4_DUTR_YMD IS NOT NULL OR T7.STG3_DUTR_YMD IS NOT NULL OR T7.STG2_DUTR_YMD IS NOT NULL THEN '훈련중' ELSE ( CASE WHEN T7.STG4_ENTRY_WAIT_YMD IS NOT NULL OR T7.STG3_ENTRY_WAIT_YMD IS NOT NULL OR T7.STG2_ENTRY_WAIT_YMD IS NOT NULL THEN '진입대기' ELSE '' END ) END ) END ) END ) STEP_DETAIL_TOT /*참여상태-상태*/ , T7.OCCP_ABILIT_STRNGT_MDSTRM_FAILR_CS_LCLAS_SE_CD /*직업역량강화중도탈락사유대분류구분코드*/ , T7.OCCP_ABILIT_STRNGT_MDSTRM_FAILR_CS_SCLAS_SE_CD /*직업역량강화중도탈락사유소분류구분코드*/ , T7.OCCP_ABILIT_STRNGT_MDSTRM_FAILR_CS_ETC_CN /*직업역량강화중도탈락사유기타내용*/ , ( SELECT C.CMMNS_CD_VALUE_NM FROM SAC100 C WHERE C.CMMNS_CD_ID = 'OCCP_ABILIT_STRNGT_MDSTRM_FAILR_CS_LCLAS_SE_CD' AND C.CMMNS_CD_VALUE = T7.OCCP_ABILIT_STRNGT_MDSTRM_FAILR_CS_LCLAS_SE_CD ) OCCP_ABILIT_STRNGT_MDSTRM_FAILR_CS_LCLAS_SE_NM , ( SELECT C.CMMNS_CD_VALUE_NM FROM SAC100 C WHERE C.CMMNS_CD_ID = 'OCCP_ABILIT_STRNGT_MDSTRM_FAILR_CS_SCLAS_SE_CD' AND C.CMMNS_CD_VALUE = T7.OCCP_ABILIT_STRNGT_MDSTRM_FAILR_CS_SCLAS_SE_CD ) OCCP_ABILIT_STRNGT_MDSTRM_FAILR_CS_SCLAS_SE_NM
, (select sum(b.GRDNG_SCORE) from SBB510 b where b.QUSTNB_MNG_NO = T7.BEFFAT_QUSTNB_MNG_NO and b.SRVY_RSPNS_MNG_NO = T7.BEFFAT_SRVY_RSPNS_MNG_NO and b.QUSTNB_TMPT_MNG_NO = T7.BEFFAT_QUSTNB_TMPT_MNG_NO ) BEFFAT_GRDNG_SCORE /*사전채점점수*/ , (select sum(b.GRDNG_SCORE) from SBB510 b where b.QUSTNB_MNG_NO = T7.AFTFCT_QUSTNB_MNG_NO and b.SRVY_RSPNS_MNG_NO = T7.AFTFCT_SRVY_RSPNS_MNG_NO and b.QUSTNB_TMPT_MNG_NO = T7.AFTFCT_QUSTNB_TMPT_MNG_NO ) AFTFCT_GRDNG_SCORE /*사후채점점수*/ , T2.INDV_IDNTFC_NO /* 2022.08.22 Lee SeungYeon - 권한적용을 위한 항목 추가 */ , T4.CASE_PIC_NO AS ENFSN_NO /* 사례담당자번호(종사자번호) */ , T4.PIC_INST_NO AS INST_NO /* 담당자기관번호(기관번호) */ , T7.STG1_PTCPTN_STTS_SE_CD , (SELECT C.CMMNS_CD_VALUE_NM FROM SAC100 C WHERE C.CMMNS_CD_ID = 'STG1_PTCPTN_STTS_SE_CD' AND C.CMMNS_CD_VALUE = T7.STG1_PTCPTN_STTS_SE_CD ) AS STG1_PTCPTN_STTS_SE_NM , T7.STG2_FNSH_YMD , T7.STG2_MDSTRM_FAILR_YMD , T7.STG3_FNSH_YMD , T7.STG3_MDSTRM_FAILR_YMD , T7.STG4_FNSH_YMD , T7.STG4_MDSTRM_FAILR_YMD , ( SELECT LISTAGG(B.CMMNS_CD_VALUE_NM||'-'||C.CMMNS_CD_VALUE_NM|| DECODE(D.CMMNS_CD_VALUE_NM, '','','-'||D.CMMNS_CD_VALUE_NM), CHR(10)) WITHIN GROUP (ORDER BY B.CMMNS_CD_VALUE_NM) FROM AKA130 A, SAC100 B, SAC100 C, SAC100 D WHERE 1 = 1 AND A.CASE_MNG_NO = T1.CASE_MNG_NO AND A.CASE_MNG_ODRNO = T1.CASE_MNG_ODRNO AND A.UNT_TASKWK_SE_CD = T1.UNT_TASKWK_SE_CD AND A.OUTC_CN_LCLAS_SE_CD = B.CMMNS_CD_VALUE(+) AND B.CMMNS_CD_ID(+) = 'OUTC_CN_LCLAS_SE_CD' AND A.OUTC_CN_MLSFC_SE_CD = C.CMMNS_CD_VALUE(+) AND C.CMMNS_CD_ID(+) = 'OUTC_CN_MLSFC_SE_CD' AND A.OUTC_CN_SCLAS_SE_CD = D.CMMNS_CD_VALUE(+) AND D.CMMNS_CD_ID(+) = 'OUTC_CN_SCLAS_SE_CD') AS OUTC_CN , CASE WHEN T7.STG4_MDSTRM_FAILR_YMD IS NOT NULL THEN '4단계' WHEN T7.STG3_MDSTRM_FAILR_YMD IS NOT NULL THEN '3단계' WHEN T7.STG2_MDSTRM_FAILR_YMD IS NOT NULL THEN '2단계' ELSE '' END AS MDSTRM_FAILR FROM SEB100 T1 , SEA200 T2 , SCA300 T3 , SEB150 T4 , SCA100 T5 , SAA000 T6 , AKA100 T7
WHERE 1 = 1 AND T1.TRPR_INFO_NO = T2.TRPR_INFO_NO AND T2.INDV_IDNTFC_NO = T3.INDV_IDNTFC_NO(+) AND T1.CASE_MNG_NO = T4.CASE_MNG_NO AND T1.CASE_MNG_ODRNO = T4.CASE_MNG_ODRNO AND T5.ENFSN_NO = T4.CASE_PIC_NO AND T6.INST_NO = T4.PIC_INST_NO AND T4.PCHPRS_YN = 'Y' and T1.CASE_MNG_NO = T7.CASE_MNG_NO(+) and T1.CASE_MNG_ODRNO = T7.CASE_MNG_ODRNO(+)
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
AND TO_CHAR(T1.FRST_REG_DT, 'YYYYMMDD') BETWEEN #{START_DATE} AND #{END_DATE}
AND T2.TRPR_NM_ENCPT = C##RG.ENC_B64(#{TRPR_NM_ENCPT})
AND T1.YNGBGS_SE_NO LIKE '%' || #{YNGBGS_STTS_LCLAS_SE_CD} || '%'
AND T1.YNGBGS_STTS_SCLAS_SE_CD = #{YNGBGS_STTS_SCLAS_SE_CD}
AND T5.FLNM_ENCPT = C##RG.ENC_B64(#{PIC_NM_ENCPT})
AND(T6.INST_NO = #{INST_NO} OR T6.INST_NM = #{INST_NM})
AND T2.CASE_TRPR_TYPE_SE_CD = #{CASE_TRPR_TYPE_SE_CD}
AND T1.CASE_PRGRS_STTS_SE_CD IN (SELECT CMMNS_CD_VALUE FROM SAC100 WHERE CMMNS_CD_ID = 'CASE_PRGRS_STTS_SE_CD' AND UP_CMMNS_CD_VALUE = #{CASE_PRGRS_STTS_SE_CD})
AND T1.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
AND REGEXP_LIKE(T1.TAG_NO, '(' || REPLACE(#{TAG_NO},',','|') || ')') -- 태그번호
AND T2.RCPT_PIC_NO = #{USER_ID}
ORDER BY T1.FRST_REG_DT DESC, T1.CASE_MNG_NO, T1.CASE_MNG_ODRNO DESC

mapper.update:
 /* isry.drmgs.casereg.mapper.DrmgsCaseRegMapper.mergeSBB100 - 응용2팀 강화영  */

 MERGE INTO
        SBB110      AA      /** 설문대상자 **/
USING   DUAL
    ON
    (
        AA.QUSTNB_MNG_NO      =   #{QUSTNB_MNG_NO}
        AND AA.QUSTNB_TMPT_MNG_NO      =   #{QUSTNB_TMPT_MNG_NO}
    )
WHEN MATCHED THEN
    UPDATE SET
    AA.LAST_MDFR_ID         =   #{LAST_MDFR_ID}
    ,   AA.LAST_MDFCN_DT        =   SYSDATE
WHEN NOT MATCHED THEN 
    INSERT
    (
            AA.QUSTNB_MNG_NO
        ,   AA.QUSTNB_TMPT_MNG_NO
        ,   AA.CASE_MNG_NO
        ,   AA.CASE_MNG_ODRNO
        ,   AA.FRST_RGTR_ID

    )
    VALUES
    (
            #{QUSTNB_MNG_NO}
        ,   #{QUSTNB_TMPT_MNG_NO}
        ,   #{CASE_MNG_NO}
        ,   #{CASE_MNG_ODRNO}
        ,   #{FRST_RGTR_ID}
    )

/* isry.drmgs.casereg.mapper.DrmgsCaseRegMapper.mergeSBB500 - 응용2팀 강화영  */

MERGE INTO
        SBB500      AA      /** 설문응답 **/
USING   DUAL
    ON
    (
            AA.QUSTNB_MNG_NO      =   #{QUSTNB_MNG_NO, jdbcType=VARCHAR}
        AND AA.QUSTNB_TMPT_MNG_NO =   #{QUSTNB_TMPT_MNG_NO, jdbcType=VARCHAR}
        AND AA.SRVY_RSPNS_MNG_NO  =   #{SRVY_RSPNS_MNG_NO, jdbcType=VARCHAR}
    )
WHEN MATCHED THEN
    UPDATE SET
        AA.RSPNS_DT             =   SYSDATE
    ,   AA.CNTN_IP_ADDR       =   #{CNTN_IP_ADDR}
    ,   AA.LAST_MDFR_ID         =   #{LAST_MDFR_ID}
    ,   AA.LAST_MDFCN_DT        =   SYSDATE 
WHEN NOT MATCHED THEN 
    INSERT
    (
            AA.QUSTNB_MNG_NO
        ,   AA.QUSTNB_TMPT_MNG_NO
        ,   AA.SRVY_RSPNS_MNG_NO
        ,   AA.UNT_TASKWK_SE_CD 
        ,   AA.USER_ID
        ,   AA.CASE_MNG_NO
        ,   AA.CASE_MNG_ODRNO
        ,   AA.RSPNS_DT
        ,   AA.CNTN_IP_ADDR
        ,   AA.FRST_RGTR_ID
    )
    VALUES
    (
            #{QUSTNB_MNG_NO}
        ,   #{QUSTNB_TMPT_MNG_NO}
        ,   #{SRVY_RSPNS_MNG_NO}
        ,   'U03' 
        ,   (select c.USER_ID from SEA200 a, SEB100 b, SAA200 c
            where a.TRPR_INFO_NO = b.TRPR_INFO_NO
            and a.INDV_IDNTFC_NO = c.INDV_IDNTFC_NO
            and b.CASE_MNG_NO = #{CASE_MNG_NO} and b.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
            )
        ,   #{CASE_MNG_NO}
        ,   #{CASE_MNG_ODRNO}
        ,   SYSDATE
        ,   #{CNTN_IP_ADDR}
        ,   #{FRST_RGTR_ID}
    )

mapper.delete:
/* isry.drmgs.casereg.mapper.DrmgsCaseRegMapper.deleteSBB220 - 응용2팀 강화영  */

delete from SBB220
where SRVY_RSPNS_MNG_NO = #{SRVY_RSPNS_MNG_NO}

mapper.insert:
