			, FRST_RGTR_ID
        ) values (
            #{QESITM_MNG_NO}
            , #{SRVY_RSPNS_MNG_NO}
            , #{CHTY_QESITM_RSPNS_VALUE}
            , #{QESITM_RSPNS_CN}
            , #{FRST_RGTR_ID}
        )

mapper.update:
MERGE INTO
        SBB510      AA      /** 채점결과 **/
USING   DUAL
    ON
    (
            AA.QUSTNB_MNG_NO            =   #{QUSTNB_MNG_NO, jdbcType=VARCHAR}
        AND AA.SRVY_RSPNS_MNG_NO        =   #{SRVY_RSPNS_MNG_NO, jdbcType=VARCHAR}
        AND AA.QUSTNB_GRDNG_RELM_MNG_NO =   #{QUSTNB_GRDNG_RELM_MNG_NO, jdbcType=VARCHAR}
    )
WHEN MATCHED THEN
    UPDATE SET
    AA.GRDNG_SCORE       =   #{GRDNG_SCORE}
    ,   AA.LAST_MDFR_ID         =   #{LAST_MDFR_ID}
    ,   AA.LAST_MDFCN_DT        =   SYSDATE 
WHEN NOT MATCHED THEN 
    INSERT
    (
            AA.QUSTNB_MNG_NO
        ,   AA.SRVY_RSPNS_MNG_NO
        ,   AA.QUSTNB_TMPT_MNG_NO
        ,   AA.QUSTNB_GRDNG_RELM_MNG_NO 
        ,   AA.GRDNG_RESULT_MNG_NO
        ,   AA.UNT_TASKWK_SE_CD
        ,   AA.GRDNG_SCORE
        ,   AA.FRST_RGTR_ID
    )
    VALUES
    (
        #{QUSTNB_MNG_NO}
        ,   #{SRVY_RSPNS_MNG_NO}
        ,   #{QUSTNB_TMPT_MNG_NO}
        ,   #{QUSTNB_GRDNG_RELM_MNG_NO} 
        ,   (SELECT ISRY_APP.SA_FN_GET_RENU_NO('SO', #{FRST_RGTR_ID}, TO_CHAR(SYSDATE,'YYYYMMDD')) /* 문항관리번호 */
                FROM DUAL)
        ,   'U03'
        ,   #{GRDNG_SCORE}
        ,   #{FRST_RGTR_ID}
    )

/* isry.drmgs.casereg.mapper.DrmgsCaseRegMapper.updateChupAKA000 - 응용2팀 강화영  */

MERGE INTO
        AKA000      AA      /** 사례관리-등록고유 **/
USING   DUAL
    ON
    (
            AA.CASE_MNG_NO     =   #{CASE_MNG_NO, jdbcType=VARCHAR}
        AND AA.CASE_MNG_ODRNO  =   #{CASE_MNG_ODRNO, jdbcType=VARCHAR}
    )
WHEN MATCHED THEN
    UPDATE SET
    AA.CHUP_INSPTN_TRPR_YN     =   #{CHUP_INSPTN_TRPR_YN}
    ,   AA.LAST_MDFR_ID        =   #{USER_ID}
    ,   AA.LAST_MDFCN_DT       =   SYSDATE 
WHEN NOT MATCHED THEN
    INSERT
    (
            AA.CASE_MNG_NO
        ,   AA.CASE_MNG_ODRNO
        ,   AA.CHUP_INSPTN_TRPR_YN
        ,   AA.FRST_RGTR_ID
    )
    VALUES
    (
            #{CASE_MNG_NO}
        ,   #{CASE_MNG_ODRNO}
        ,   #{CHUP_INSPTN_TRPR_YN} 
        ,   #{USER_ID}
    )

mapper.insert:
        /* isry.drmgs.casereg.mapper.DrmgsCaseRegMapper.insertChupAKA001 - 응용2팀 강화영  */

        insert into AKA001 (
            CASE_MNG_NO
			, CASE_MNG_ODRNO
			, INSPTN_YN
			, INSPTN_YMD
			, FRST_RGTR_ID
        ) values (
            #{CASE_MNG_NO}
            , #{CASE_MNG_ODRNO}
            , #{INSPTN_YN}
            , #{INSPTN_YMD}
            , #{USER_ID}
        )

mapper.update:
/* isry.drmgs.casereg.mapper.DrmgsCaseRegMapper.updateChupAKA001 - 응용2팀 강화영  */

update AKA001 set
INSPTN_YN = #{INSPTN_YN}
, INSPTN_YMD = #{INSPTN_YMD}
, LAST_MDFR_ID = #{USER_ID}
, LAST_MDFCN_DT = SYSDATE 
where CASE_MNG_NO = #{CASE_MNG_NO, jdbcType=VARCHAR}
AND CASE_MNG_ODRNO = #{CASE_MNG_ODRNO, jdbcType=VARCHAR}
AND INSPTN_YMD = #{INSPTN_YMD}

mapper.delete:
/* isry.drmgs.casereg.mapper.DrmgsCaseRegMapper.deleteChupAKA001 - 응용2팀 강화영  */

delete from AKA001
where CASE_MNG_NO = #{CASE_MNG_NO, jdbcType=VARCHAR}
AND CASE_MNG_ODRNO = #{CASE_MNG_ODRNO, jdbcType=VARCHAR}
AND INSPTN_YMD = #{INSPTN_YMD}

