mapper.select:
/* isry.drmgs.casereg.mapper.DrmgsCaseRegMapper.selectChupInfo  */
SELECT T1.CASE_MNG_NO                       AS CASE_MNG_NO          /* 사례관리번호 */
     , T1.CASE_MNG_ODRNO                    AS CASE_MNG_ODRNO       /* 사례관리차수 */
     , NVL(T1.CHUP_INSPTN_TRPR_YN, 'N')     AS CHUP_INSPTN_TRPR_YN  /* 건강검진수검대상자여부 */
  FROM AKA000 T1   /* 사례관리-등록고유-건강검진수검대 */
 WHERE T1.CASE_MNG_NO    = #{CASE_MNG_NO}
   AND T1.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}

/* isry.drmgs.casereg.mapper.DrmgsCaseRegMapper.selectQusList  */
SELECT QUSTNB_MNG_NO
     , QUSTNB_TMPT_MNG_NO
     , CASE_MNG_NO
     , CASE_MNG_ODRNO
     , CASE_TRPR_NM_ENCPT
FROM SBB110
WHERE CASE_MNG_NO = #{CASE_MNG_NO} 
  AND CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}

/* isry.drmgs.casereg.mapper.DrmgsCaseRegMapper.selectCaseInspSrvyList - 응용3팀 이승연 */ SELECT T1.CASE_MNG_NO AS CASE_MNG_NO /* 사례관리번호 */ , T1.CASE_MNG_ODRNO AS CASE_MNG_ODRNO /* 사례관리차수 */ , T1.INDEX_SN AS INDEX_SN /* 색인일련번호 */ , T1.QUSTNB_TMPT_MNG_NO AS QUSTNB_TMPT_MNG_NO /* 설문지템플릿관리번호 */ , T1.QUSTNB_MNG_NO AS QUSTNB_MNG_NO /* 설문지관리번호 */ , T1.SRVY_RSPNS_MNG_NO AS SRVY_RSPNS_MNG_NO /* 설문응답관리번호 */ , T1.INSP_SRVY_TYPE_CL_SE_CD AS INSP_SRVY_TYPE_CL_SE_CD /* 검사설문유형분류코드 */ , T1.INSP_YMD AS INSP_YMD /* 검사일자 */ , T1.INSP_RESULT_CN AS INSP_RESULT_CN /* 검사결과내용 */ /* 정서.행동특성검사 */ , T1.INSP_KND_SE_CD AS INSP_KND_SE_CD /* 검사종류구분코드 */ , T1.INSP_RESULT_SCORE AS INSP_RESULT_SCORE /* 검사결과점수 */ , T1.SUCDE_ITRVW_RCORDP_WRT_YN AS SUCDE_ITRVW_RCORDP_WRT_YN /* 자살면담기록지작성여부 */ , T1.QUSTNB_TMPT_MNG_NO2 AS QUSTNB_TMPT_MNG_NO2 /* 설문지템플릿관리번호2 */ , T1.QUSTNB_MNG_NO2 AS QUSTNB_MNG_NO2 /* 설문지관리번호2 */ , T1.SRVY_RSPNS_MNG_NO2 AS SRVY_RSPNS_MNG_NO2 /* 설문응답관리번호2 */ /* 인터넷.스마트폰진단 */ , T1.INTNET_SMRTP_DGNSS_CL_SE_CD AS INTNET_SMRTP_DGNSS_CL_SE_CD /* 인터넷스마트폰진단분류구분코드 */ , T1.INTNET_DGNSS_SUM_SCORE AS INTNET_DGNSS_SUM_SCORE /* 인터넷진단합계점수 */ , T1.INTNET_DGNSS_FCTR_SCORE1 AS INTNET_DGNSS_FCTR_SCORE1 /* 인터넷진단요인점수1 */ , T1.INTNET_DGNSS_FCTR_SCORE3 AS INTNET_DGNSS_FCTR_SCORE3 /* 인터넷진단요인점수3 */ , T1.INTNET_DGNSS_FCTR_SCORE4 AS INTNET_DGNSS_FCTR_SCORE4 /* 인터넷진단요인점수4 */ /* 전문 프로그램 만족도 관리 */ , T1.SPCLTY_PROGRM_DGSTFN_CL_SE_CD AS SPCLTY_PROGRM_DGSTFN_CL_SE_CD /* 전문프로그램만족도분류코드 */ , T1.BEFFAT_AFTFCT_SE_CD AS BEFFAT_AFTFCT_SE_CD /* 사전사후구분코드 */ , T1.DEL_YN AS DEL_YN /* 삭제여부 */ , ( SELECT X.ADDTNG_MNG_VALUE1 FROM SAC100 X WHERE X.CMMNS_CD_ID = 'SPCLTY_PROGRM_DGSTFN_CL_SE_CD' AND X.CMMNS_CD_VALUE = T1.SPCLTY_PROGRM_DGSTFN_CL_SE_CD AND T1.BEFFAT_AFTFCT_SE_CD = 'PRE' ) AS PRE_QUSTNB_TMPT_MNG_NO /* 사전_설문지템플릿관리번호 */ , ( SELECT X.ADDTNG_MNG_VALUE2 FROM SAC100 X WHERE X.CMMNS_CD_ID = 'SPCLTY_PROGRM_DGSTFN_CL_SE_CD' AND X.CMMNS_CD_VALUE = T1.SPCLTY_PROGRM_DGSTFN_CL_SE_CD AND T1.BEFFAT_AFTFCT_SE_CD = 'AF' ) AS AF_QUSTNB_TMPT_MNG_NO /* 사후_설문지템플릿관리번호 */ , ( SELECT X.ADDTNG_MNG_VALUE2 FROM SAC100 X WHERE X.CMMNS_CD_ID = 'INSP_KND_SE_CD' AND X.CMMNS_CD_VALUE = T1.INSP_KND_SE_CD ) AS SUCDE_ITRVW_RCORDP_TMPT_MNG_NO /* 자살면담기록지템플릿관리번호 */ , T1.SUCDE_ITRVW_RCORDP_WRT_YN AS SUICIDE_SRVY_YN /* 자살면담기록지대상여부 */ /* 심리정서, 환경 척도*/ , T1.TRL_EMT_ENVRN_SE_CD_NM AS TRL_EMT_ENVRN_SE_CD_NM /* 심리정서환경구분코드명 */ , T1.ANXIET_DEPRES_SCORE AS ANXIET_DEPRES_SCORE /* 불안우울점수 */ , T1.SURPLU_GHVR_ATENTA_CNCTR_IMPLS_SCORE AS SURPLU_GHVR_ATENTA_CNCTR_IMPLS_SCORE /* 과잉행동주의집중충동점수 */ , T1.DEFIAN_CNDCT_SCORE AS DEFIAN_CNDCT_SCORE /* 반항품행점수 */ , T1.DELUSI_AUHA_SCORE AS DELUSI_AUHA_SCORE /* 망상환청점수 */ , T1.ADDC_SCORE AS ADDC_SCORE /* 중독점수 */ , T1.SUCDE_SLFIJR_SCORE AS SUCDE_SLFIJR_SCORE /* 자살자해점수 */ , T1.HOUSEK_ENVRN_SCORE AS HOUSEK_ENVRN_SCORE /* 가정환경점수 */ , T1.FRIDA_ENVRN_SCORE AS FRIDA_ENVRN_SCORE /* 또래환경점수 */ , T1.RGN_SOCTY_ENVRN_SCORE AS RGN_SOCTY_ENVRN_SCORE /* 지역사회환경점수 */ , T1.PARNTS_SNDTER_REL_SCORE AS PARNTS_SNDTER_REL_SCORE /* 부모자녀관계점수 */ /* 자립역량 척도*/ , T1.SLFRL_ABILIT_SE_CD_NM AS SLFRL_ABILIT_SE_CD_NM /* 자립역량구분코드명 */ , T1.PRTCTN_FCTR_SCORE AS PRTCTN_FCTR_SCORE /* 보호요인점수 */ , T1.DIGNIT_SCORE AS DIGNIT_SCORE /* 자존감점수 */ , T1.SINCER_SCORE AS SINCER_SCORE /* 성실성점수 */ , T1.SCHULW_EFFICA_SCORE AS SCHULW_EFFICA_SCORE /* 학업효능감점수 */ , T1.COSE_INFO_EXPLR_ACTVT_SCORE AS COSE_INFO_EXPLR_ACTVT_SCORE /* 진로정보탐색활동점수 */ , T1.SOCIAL_SEOFCO_SCORE AS SOCIAL_SEOFCO_SCORE /* 사회적유능감 */
, T1.ANXIET_DEPRES_RESULT_NM AS ANXIET_DEPRES_RESULT_NM /* 불안우울결과 */ , T1.SURPLU_GHVR_ATENTA_CNCTR_IMPLS_RESULT_NM AS SURPLU_GHVR_ATENTA_CNCTR_IMPLS_RESULT_NM /* 과잉행동주의집중충동결과 */ , T1.DEFIAN_CNDCT_RESULT_NM AS DEFIAN_CNDCT_RESULT_NM /* 반항품행결과 */ , T1.DELUSI_AUHA_RESULT_NM AS DELUSI_AUHA_RESULT_NM /* 망상환청결과 */ , T1.ADDC_RESULT_NM AS ADDC_RESULT_NM /* 중독결과 */ , T1.SUCDE_SLFIJR_RESULT_NM AS SUCDE_SLFIJR_RESULT_NM /* 자살자해결과 */ , T1.HOUSEK_ENVRN_RESULT_NM AS HOUSEK_ENVRN_RESULT_NM /* 가정환경결과 */ , T1.FRIDA_ENVRN_RESULT_NM AS FRIDA_ENVRN_RESULT_NM /* 또래환경결과 */ , T1.RGN_SOCTY_ENVRN_RESULT_NM AS RGN_SOCTY_ENVRN_RESULT_NM /* 지역사회환경결과 */ , T1.PARNTS_SNDTER_REL_RESULT_NM AS PARNTS_SNDTER_REL_RESULT_NM /* 부모자녀관계결과 */ /* 자립역량 척도*/ , T1.PRTCTN_FCTR_RESULT_NM AS PRTCTN_FCTR_RESULT_NM /* 보호요인결과 */ , T1.DIGNIT_RESULT_NM AS DIGNIT_RESULT_NM /* 자존감결과 */ , T1.SINCER_RESULT_NM AS SINCER_RESULT_NM /* 성실성결과 */ , T1.SCHULW_EFFICA_RESULT_NM AS SCHULW_EFFICA_RESULT_NM /* 학업효능감결과 */ , T1.COSE_INFO_EXPLR_ACTVT_RESULT_NM AS COSE_INFO_EXPLR_ACTVT_RESULT_NM /* 진로정보탐색활동결과 */ , T1.SOCIAL_SEOFCO_RESULT_NM AS SOCIAL_SEOFCO_RESULT_NM /* 사회적유능감 */ FROM AKA010 T1 /* 검사설문 */ WHERE T1.CASE_MNG_NO = #{CASE_MNG_NO} /* 사례관리번호 */ AND T1.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO} /* 사례관리차수 */ AND T1.DEL_YN != 'Y' /* 삭제여부 != 'Y' */
AND T1.INSP_SRVY_TYPE_CL_SE_CD = #{INSP_SRVY_TYPE_CL_SE_CD} /* 검사설문유형분류코드 */

mapper.insert:

