			,   AA.HPE_SRVC_DMD_ETC_CN2         =   #{HPE_SRVC_DMD_ETC_CN2}  /*  희망서비스수요기타내용2    */
			,   AA.HPE_SRVC_DMD_ETC_CN3         =   #{HPE_SRVC_DMD_ETC_CN3}  /*  희망서비스수요기타내용3    */
			,   AA.HPE_SRVC_DMD_ETC_CN4         =   #{HPE_SRVC_DMD_ETC_CN4}  /*  희망서비스수요기타내용4    */
			,   AA.HPE_SRVC_DMD_ETC_CN5         =   #{HPE_SRVC_DMD_ETC_CN5}  /*  희망서비스수요기타내용5    */
			,   AA.LAST_MDFR_ID                 =   #{USER_ID}  /*  최종수정자아이디    */
            ,   AA.LAST_MDFCN_DT                =   SYSDATE /*  최종수정일시  */
        WHEN NOT MATCHED THEN 
