				,   AA.HPE_SRVC_RANKSE_GOAL_SE_CD  /*  희망서비스2순위목표구분코드  */
				,   AA.HPE_SRVC_RANKTH_GOAL_SE_CD  /*  희망서비스3순위목표구분코드  */
				,   AA.HPE_SRVC_GOAL_ETC_CN    /*  희망서비스목표기타내용 */
				,   AA.HPE_SRVC_DMD_SE_CD_NM   /*  희망서비스수요구분코드명    */
