				,   AA.HPE_SRVC_DMD_ETC_CN2    /*  희망서비스수요기타내용2    */
				,   AA.HPE_SRVC_DMD_ETC_CN3    /*  희망서비스수요기타내용3    */
				,   AA.HPE_SRVC_DMD_ETC_CN4    /*  희망서비스수요기타내용4    */
				,   AA.HPE_SRVC_DMD_ETC_CN5    /*  희망서비스수요기타내용5    */
				,   AA.FRST_RGTR_ID    /*  최초등록자아이디    */
